using LgymApi.Application.Identity.Contracts.Accounts; using LgymApi.Application.Notifications.Contracts.Events; using LgymApi.Application.Notifications.Contracts.InApp; using LgymApi.Domain.Entities; using LgymApi.Domain.ValueObjects; using Microsoft.Extensions.Logging;
namespace LgymApi.Application.Notifications.Contracts.InApp { public sealed record RelationshipEndedDeliveryRequest(string TrainerId,string TraineeId,string? TrainerName,string? TrainerEmail,string? TrainerCulture,string? TrainerZone,string? TraineeName,string? TraineeEmail,string? TraineeCulture,string? TraineeZone); public interface IRelationshipEndedDeliveryPort { Task DeliverAsync(RelationshipEndedDeliveryRequest request,CancellationToken ct=default); } }
namespace LgymApi.Application.Notifications.InApp { internal sealed class RelationshipEndedDeliveryService(ICoachingNotificationIntentService intents,ILogger<RelationshipEndedDeliveryService> logger):IRelationshipEndedDeliveryPort { public async Task DeliverAsync(RelationshipEndedDeliveryRequest r,CancellationToken ct=default) { if(!Id<User>.TryParse(r.TrainerId,out var trainerId)||!Id<User>.TryParse(r.TraineeId,out var traineeId))return; var trainer=r.TrainerName is null?null:new AccountReadModel(trainerId,r.TrainerName,r.TrainerEmail!,null,r.TrainerCulture!,r.TrainerZone!); var trainee=r.TraineeName is null?null:new AccountReadModel(traineeId,r.TraineeName,r.TraineeEmail!,null,r.TraineeCulture!,r.TraineeZone!); var result=await intents.SubmitAsync(new RelationshipEndedCoachingNotificationIntent(CoachingNotificationLegacyChannel.InApp,trainerId,traineeId,trainer,trainee),ct); if(result.InAppError is not null) logger.LogError($"Failed to create trainer-relationship-ended notification for trainer {trainerId}: {result.InAppError}"); } } }
